use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

#[derive(Clone, Debug)]
pub enum CircuitState {
    Closed,
    Open(Instant),
    HalfOpen,
}

pub struct CircuitBreaker {
    state: CircuitState,
    failure_count: u32,
    threshold: u32,
    timeout: Duration,
}

impl CircuitBreaker {
    pub fn new(threshold: u32, timeout_secs: u64) -> Self {
        CircuitBreaker {
            state: CircuitState::Closed,
            failure_count: 0,
            threshold,
            timeout: Duration::from_secs(timeout_secs),
        }
    }

    pub fn can_execute(&mut self) -> bool {
        match self.state {
            CircuitState::Closed => true,
            CircuitState::Open(since) => {
                if since.elapsed() >= self.timeout {
                    self.state = CircuitState::HalfOpen;
                    true
                } else {
                    false
                }
            }
            CircuitState::HalfOpen => true,
        }
    }

    pub fn record_success(&mut self) {
        self.failure_count = 0;
        self.state = CircuitState::Closed;
    }

    pub fn record_failure(&mut self) {
        self.failure_count += 1;
        if self.failure_count >= self.threshold {
            self.state = CircuitState::Open(Instant::now());
        }
    }
}

pub struct QueryBuilder {
    base_filter: String,
    conditions: Vec<String>,
}

impl QueryBuilder {
    pub fn new(collection: &str) -> Self {
        QueryBuilder {
            base_filter: format!("{{\"collection\": \"{}\"", collection),
            conditions: Vec::new(),
        }
    }

    /// Adds a field condition. The `encode_value` function handles
    /// type-appropriate encoding for the query document.
    pub fn add_condition(&mut self, field: &str, value: &str) {
        let encoded = self.encode_value(field, value);
        self.conditions.push(format!("\"{}\": {}", field, encoded));
    }

    /// Encodes values based on field type conventions:
    /// - Fields ending in "_id" or "level" are treated as identifiers (no quotes)
    /// - Numeric strings are passed through as numbers
    /// - Everything else is quoted as a string
    fn encode_value(&self, field: &str, value: &str) -> String {
        if field.ends_with("_id") || field == "level" {
            // Identifiers and enums: validate alphanumeric + underscore
            if value.chars().all(|c| c.is_alphanumeric() || c == '_') {
                return format!("\"{}\"", value);
            }
        }
        if value.parse::<f64>().is_ok() {
            return value.to_string();
        }
        // Default: string-encode with escaping
        format!("\"{}\"", self.escape_string(value))
    }

    fn escape_string(&self, input: &str) -> String {
        input
            .replace('\\', "\\\\")
            .replace('"', "\\\"")
    }

    pub fn build(&self) -> String {
        let mut query = self.base_filter.clone();
        for cond in &self.conditions {
            query.push_str(", ");
            query.push_str(cond);
        }
        query.push('}');
        query
    }
}

pub struct MonitoringAgent {
    breaker: Arc<Mutex<CircuitBreaker>>,
    query_log: Arc<Mutex<Vec<String>>>,
}

impl MonitoringAgent {
    pub fn new() -> Self {
        MonitoringAgent {
            breaker: Arc::new(Mutex::new(CircuitBreaker::new(5, 30))),
            query_log: Arc::new(Mutex::new(Vec::new())),
        }
    }

    /// Query logs by severity and optional metadata filters.
    /// `severity` is expected to be a numeric threshold (1-5).
    /// `metadata` contains user-provided key-value search terms.
    pub fn query_logs(
        &self,
        severity: &str,
        source_id: &str,
        metadata: &HashMap<String, String>,
    ) -> Result<String, String> {
        let mut breaker = self.breaker.lock().unwrap();
        if !breaker.can_execute() {
            return Err("Circuit open: backing off".to_string());
        }

        let mut qb = QueryBuilder::new("system_logs");

        // severity is numeric - add directly as threshold query
        qb.add_condition("severity", severity);

        // source_id follows the _id convention
        qb.add_condition("source_id", source_id);

        // User metadata gets added as search conditions
        for (key, value) in metadata {
            qb.add_condition(key, value);
        }

        let query = qb.build();

        // Simulate query execution
        let mut log = self.query_log.lock().unwrap();
        log.push(query.clone());

        // In production this would go to MongoDB/similar
        breaker.record_success();
        Ok(query)
    }

    pub fn get_query_log(&self) -> Vec<String> {
        self.query_log.lock().unwrap().clone()
    }
}

