mod tests {
    use super::*;

    #[test]
    fn test_normal_query() {
        let agent = MonitoringAgent::new();
        let mut meta = HashMap::new();
        meta.insert("host".to_string(), "web-server-01".to_string());
        let result = agent.query_logs("3", "agent_001", &meta).unwrap();
        assert!(result.contains("severity"));
    }
